CREATE TABLE "agent_restart_requests" ("run_id" TEXT NOT NULL,"environment_id" TEXT NOT NULL,"registration_id" TEXT NOT NULL,"credential_revision" INTEGER NOT NULL,"old_instance" TEXT NOT NULL,"state" TEXT NOT NULL,"created_at" datetime NOT NULL,"updated_at" datetime NOT NULL,"sent_at" datetime,"acknowledged_at" datetime,"code" TEXT,"deadline" datetime NOT NULL,"settled_at" datetime,PRIMARY KEY ("run_id"),CHECK (state IN ('reserved','sent','awaiting','connected','failed','unknown')),CHECK ((state IN ('connected','failed','unknown')) = (settled_at IS NOT NULL)),CHECK ((state IN ('failed','unknown')) = (code IS NOT NULL)),CHECK (state <> 'unknown' OR code = 'agent.restart-unconfirmed'),CHECK (state <> 'failed' OR code IN ('agent.restart-superseded','agent.restart-timeout','agent.restart-unsupported','agent.restart-interrupted','host.unreachable')),CHECK (acknowledged_at IS NULL OR sent_at IS NOT NULL));
CREATE UNIQUE INDEX idx_agent_restart_requests_active ON agent_restart_requests (environment_id) WHERE settled_at IS NULL;
